function reset() {
  player = { x: 40, y: 40, size: 18, speed: 190 };
  coin = randomPosition();
  enemy = { x: 410, y: 250, size: 22, speed: 75 };
  score = 0; running = true; previousTime = 0;
  scoreLabel.textContent = "Монеты: 0";
}
function overlaps(a, b, radiusA, radiusB) {
  return Math.hypot(a.x - b.x, a.y - b.y) < radiusA + radiusB;
}
function update(delta) {
  const dx = Number(keys.has("ArrowRight")) - Number(keys.has("ArrowLeft"));
  const dy = Number(keys.has("ArrowDown")) - Number(keys.has("ArrowUp"));
  const length = Math.hypot(dx, dy) || 1;
  player.x = Math.max(9, Math.min(471, player.x + dx / length * player.speed * delta));
  player.y = Math.max(9, Math.min(311, player.y + dy / length * player.speed * delta));
  const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
  enemy.x += Math.cos(angle) * enemy.speed * delta;
  enemy.y += Math.sin(angle) * enemy.speed * delta;
  if (overlaps(player, coin, 9, 7)) {
    score += 1; scoreLabel.textContent = "Монеты: " + score; coin = randomPosition();
  }
  if (overlaps(player, enemy, 9, 11)) running = false;
}
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#4ee29a"; ctx.fillRect(player.x - 9, player.y - 9, 18, 18);
  ctx.fillStyle = "#ffd447"; ctx.beginPath(); ctx.arc(coin.x, coin.y, 7, 0, Math.PI * 2); ctx.fill();
