  if (!running) { ctx.fillStyle = "white"; ctx.font = "24px system-ui"; ctx.fillText("Игра окончена", 145, 160); }
}
function loop(time) {
  const delta = Math.min((time - (previousTime || time)) / 1000, 0.05);
  previousTime = time;
  if (running) update(delta);
  draw();
  if (running) requestAnimationFrame(loop);
}
window.addEventListener("keydown", event => {
  if (event.key.startsWith("Arrow")) event.preventDefault();
  keys.add(event.key);
});
window.addEventListener("keyup", event => keys.delete(event.key));
document.querySelector("#restart").addEventListener("click", () => { reset(); requestAnimationFrame(loop); });
